    $scope.OnChecklistSelect = function (obj, parentobj) {

        var CheckListInd = false;
        angular.forEach(parentobj.OrganizationCheckListDetails, function (item) {
            if (obj.IsChecked == true && item.Value == obj.Value) {
                CheckListInd = true;
                item.PatientAscCheckListDetailId = item.PatientAscCheckListDetailId || null;
                if (item.PatientAscCheckListDetailId != null) {
                    item.DeleteInd = "Y";
                }
            } else {
                item.IsChecked = false;
            }

        });

        if (CheckListInd == true) {
            obj.IsChecked = false;
            parentobj.IsChecked = false;


            if (parentobj.CheckListCategoryId === 1) {
                $scope.AdmissionObj.IsAllNurseCheckListChecked = '';
            }
            if (parentobj.CheckListCategoryId === 5) {
                $scope.AdmissionObj.IsAllMedicineCheckListChecked = '';
            }
            if (parentobj.CheckListCategoryId === 6) {
                $scope.AdmissionObj.IsAllGeneralCheckListChecked = '';
            }

            if (parentobj.CheckListCategoryId === 17) {
                $scope.AdmissionObj.IsAllAdmitCheckListChecked = '';
                if (parentobj.CheckListId == 243) {
                    $scope.AdmissionCheckinObj.NPOTime = "";
                }
            }

        } else {
            obj.IsChecked = true;
            parentobj.IsChecked = true;
            parentobj.Value = obj.Value || '';
            parentobj.ChecklistDate = null;

        }



        if (parentobj.CheckListCategoryId === 1) {
            //if (obj.Value !== "N/A" && obj.Value !== "No" && obj.Value !== "Not") {
            //    parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
            //}
            if (obj.Value == "Yes" || obj.Value == "Done" || obj.Value == "Reviewed") {
                parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
                $scope.AdmissionObj.IsAllNurseCheckListChecked = $scope.AdmissionObj.IsAllNurseCheckListChecked == 1 ? $scope.AdmissionObj.IsAllNurseCheckListChecked : '';
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.AdmissionObj.IsAllNurseCheckListChecked = $scope.AdmissionObj.IsAllNurseCheckListChecked == 2 ? $scope.AdmissionObj.IsAllNurseCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.AdmissionObj.IsAllNurseCheckListChecked = $scope.AdmissionObj.IsAllNurseCheckListChecked == 3 ? $scope.AdmissionObj.IsAllNurseCheckListChecked : '';
            }
        }
        if (parentobj.CheckListCategoryId === 5) {


            if (obj.Value == "Yes" || obj.Value == "Done" || obj.Value == "Reviewed") {
                $scope.AdmissionObj.IsAllMedicineCheckListChecked = $scope.AdmissionObj.IsAllMedicineCheckListChecked == 1 ? $scope.AdmissionObj.IsAllMedicineCheckListChecked : '';
                if (parentobj.CheckListId == 40) {
                    parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
                }
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.AdmissionObj.IsAllMedicineCheckListChecked = $scope.AdmissionObj.IsAllMedicineCheckListChecked == 2 ? $scope.AdmissionObj.IsAllMedicineCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.AdmissionObj.IsAllMedicineCheckListChecked = $scope.AdmissionObj.IsAllMedicineCheckListChecked == 3 ? $scope.AdmissionObj.IsAllMedicineCheckListChecked : '';
            }
        }
        if (parentobj.CheckListCategoryId === 6) {
            if (obj.Value == "Yes" || obj.Value == "Done" || obj.Value == "Reviewed") {
                $scope.AdmissionObj.IsAllGeneralCheckListChecked = $scope.AdmissionObj.IsAllGeneralCheckListChecked == 1 ? $scope.AdmissionObj.IsAllGeneralCheckListChecked : '';
                parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.AdmissionObj.IsAllGeneralCheckListChecked = $scope.AdmissionObj.IsAllGeneralCheckListChecked == 2 ? $scope.AdmissionObj.IsAllGeneralCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                $scope.AdmissionObj.IsAllGeneralCheckListChecked = $scope.AdmissionObj.IsAllGeneralCheckListChecked == 3 ? $scope.AdmissionObj.IsAllGeneralCheckListChecked : '';
            }
        }

        if (parentobj.CheckListCategoryId === 17) {
            if (obj.Value == "Yes" || obj.Value == "Done" || obj.Value == "Reviewed") {
                $scope.AdmissionObj.IsAllAdmitCheckListChecked = $scope.AdmissionObj.IsAllAdmitCheckListChecked == 1 ? $scope.AdmissionObj.IsAllAdmitCheckListChecked : '';
                if (parentobj.CheckListId == 243) {
                    parentobj.ChecklistDate = $filter('date')(new Date(), "MM-dd-yyyy");
                    $scope.GetNPOTime();
                }
            }
            if (obj.Value == "No" || obj.Value == "Not") {
                $scope.AdmissionObj.IsAllAdmitCheckListChecked = $scope.AdmissionObj.IsAllAdmitCheckListChecked == 1 ? $scope.AdmissionObj.IsAllAdmitCheckListChecked : '';
                if (parentobj.CheckListId == 243) {
                    $scope.AdmissionCheckinObj.NPOTime = "";
                }
                $scope.AdmissionObj.IsAllAdmitCheckListChecked = $scope.AdmissionObj.IsAllAdmitCheckListChecked == 2 ? $scope.AdmissionObj.IsAllAdmitCheckListChecked : '';
            }
            if (obj.Value == "N/A") {
                if (parentobj.CheckListId == 243) {
                    $scope.AdmissionCheckinObj.NPOTime = "";
                }
                $scope.AdmissionObj.IsAllAdmitCheckListChecked = $scope.AdmissionObj.IsAllAdmitCheckListChecked == 3 ? $scope.AdmissionObj.IsAllAdmitCheckListChecked : '';
            }
        }
    };

