    $scope.AddNewGeneralCheckListShow = true;
    $scope.AddNewMedicalCheckListShow = true;
    $scope.AddNewClinicalCheckListShow = true;
    $scope.AddNewChecklist = function (item) {
        angular.forEach($scope.AdmissionObj.OrgASCChecklist, function (citem) {
            citem.IsshowAdd = false;
        });
        //if (item.CheckListCategoryId === 1 || item.CheckListCategoryId === 5 || item.CheckListCategoryId === 6) {
        //    item.IsshowAdd = true;
        //    $scope.AddNewGeneralCheckListShow = false;
        //}
        if (item.CheckListCategoryId === 6) {
            item.IsshowAdd = true;
            $scope.AddNewGeneralCheckListShow = false;
            $scope.AddNewMedicalCheckListShow = true;
            $scope.AddNewClinicalCheckListShow = true;

        }
        if (item.CheckListCategoryId === 5) {
            item.IsshowAdd = true;
            $scope.AddNewMedicalCheckListShow = false;
            $scope.AddNewGeneralCheckListShow = true;
            $scope.AddNewClinicalCheckListShow = true;
        }
        if (item.CheckListCategoryId === 1) {
            item.IsshowAdd = true;
            $scope.AddNewClinicalCheckListShow = false;
            $scope.AddNewMedicalCheckListShow = true;
            $scope.AddNewGeneralCheckListShow = true;
        }
    };

    $scope.CloseChecklistData = function (item) {
        $scope.AdmissionCheckinObj.NewChecklistName = "";
        item.IsshowAdd = false;

        if (item.CheckListCategoryId === 1) {
            $scope.AddNewClinicalCheckListShow = true;
        }
        if (item.CheckListCategoryId === 5) {
            $scope.AddNewMedicalCheckListShow = true;
        }
        if (item.CheckListCategoryId === 6) {
            $scope.AddNewGeneralCheckListShow = true;
        }
    }

    $scope.AddNewChecklistData = function (item) {
        $scope.LogObj.LogArray = [];

        if (item.CheckListCategoryId === 1) {
            $scope.AddNewClinicalCheckListShow = true;
        }
        if (item.CheckListCategoryId === 5) {
            $scope.AddNewMedicalCheckListShow = true;
        }
        if (item.CheckListCategoryId === 6) {
            $scope.AddNewGeneralCheckListShow = true;
        }

        if ($scope.AdmissionCheckinObj.NewChecklistName === "") {
            alertify.error("Please enter checklist name!");
            return false;
        }
        if ($scope.AdmissionCheckinObj.ChecklistValueType === "") {
            alertify.error("Please Select Any One Value!");
            return false;
        }
        let tempArray = [];
        if ($scope.AdmissionCheckinObj.ChecklistValueType == "1") {
            tempArray = [
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpheckListId": 0,
                    "Value": "Yes",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "No",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "N/A",
                    "DeleteInd": "N"
                }
            ];
        } else if ($scope.AdmissionCheckinObj.ChecklistValueType == "2") {
            tempArray = [
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "Done",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "Not",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "N/A",
                    "DeleteInd": "N"
                }
            ];
        } else if ($scope.AdmissionCheckinObj.ChecklistValueType == "3") {
            tempArray = [
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "Reviewed",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "Not",
                    "DeleteInd": "N"
                },
                {
                    "OrganizationPreOpCheckListValueId": 0,
                    "CheckListId": 0,
                    "OrganizationPreOpCheckListId": 0,
                    "Value": "N/A",
                    "DeleteInd": "N"
                }
            ];
        }

        let req = {
            "OrganizationPreOpCheckListId": 0,
            "ParentOrganizationId": $scope.ParenthospitalId,
            "UserId": $scope.UserId,
            "CheckListCategoryId": item.CheckListCategoryId,
            "CheckListId": 0,
            "CheckListModuleId": 1,
            "CheckListName": $scope.AdmissionCheckinObj.NewChecklistName,
            "CheckListSubTypeId": item.CheckListSubTypeId,
            "DeleteInd": "N",
            "OrganizationCheckListDetails": tempArray,
            "Logs": {},
        };

        $scope.AdmissionCheckinObj.NewChecklistName = $scope.AdmissionCheckinObj.NewChecklistName || '';
        if ($scope.AdmissionCheckinObj.NewChecklistName != '') {
            let ActionDescription = '';

            if (item.CheckListCategoryId == 5) {
                ActionDescription = `New Item for Medication Checklist in Admit for Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            } else if (item.CheckListCategoryId == 6) {
                ActionDescription = `New Item for General Checklist in Admit for Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            } else if (item.CheckListCategoryId == 1) {
                ActionDescription = `New Item for Clinical Checklist in Admit for Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
            }

            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 2,
                "SubModuleName": "Admit",
                "ScreenType": "Admit",
                "ActionType": "Added",
                "ActionDescription": ActionDescription,
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);
        }

        if ($scope.LogObj.LogArray.length > 0) {
            req.Logs = $scope.LogObj || {};
        }
        eHnoteSurgeryService.AddUpdateOrganizationPreOpCheckListData(req).then(function (resp) {
            if (resp.data.status === "Success") {
                alertify.success("Checklist added successfully!");
                $scope.AdmissionCheckinObj.ChecklistValueType = '';
                $scope.init();
            }
            if (resp.data.status === "Failure") {
                alertify.error(resp.data.Message);
            }
        }, function (err) {
            console.log(err);
        });
        $scope.CloseChecklistData(item);
    };

