    $scope.DeletePreadmitDocumentGetlist = function (item, index, mainitem) {

        item.DisplayName = item.DisplayName || "";
        if (item.DisplayName == "") {
            item.DisplayName = item.FileName;
        }
        $scope.DeleteFileUploadArray = { "DocumentID": item.DocumentID, "FileName": item.DisplayName, "Remarks": "" };

        alertify.confirm("<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre'>Are you sure you want to delete? </h4>", function () {
            $scope.LogObj.LogArray = [];
            let obj = {
                "LogId": 0,
                "ModuleId": 2,
                "ModuleName": "ASC",
                "SubModuleId": 2,
                "SubModuleName": "Admit",
                "ScreenType": "Files",
                "ActionType": "Deleted ",
                "OldActionDescription": item.DisplayName + " Files(External) in Admit",
                "NewActionDescription": "",
                "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
            };
            $scope.LogObj.LogArray.push(obj);
            var params = {
                "AppointmentID": $scope.cacheStorageItem.AppointmentId,
                "DeleteIndicator": 0,
                "ImagesArray": [],
                "UploadType": "Delete",
                "HospitalID": doctorinfo.doctordata.UserAddress[0].ExtDetails.HospitalInfo.HospitalID,
                "Remarks": "",
                "Logs": {},
            };
            if ($scope.LogObj.LogArray.length > 0) {
                params.Logs = $scope.LogObj || {};
            }
            params.ImagesArray.push($scope.DeleteFileUploadArray);
            eHnoteDiagnosisDataServices.DeleteASCDocumentList(params, onupdateDeletesuccess, onupdateDelerror);
        }, function () { });
        function onupdateDeletesuccess(response) {
            if (response.Status === 'Success') {
                alertify.success("Document Deleted successfully!");
                $scope.GetPreAdmitChartData();
            }
        }
        function onupdateDelerror(errordata) {
            console.log(errordata);
        }
    }
    $scope.GetPreAdmitChartData = function () {
        let req = {
            "AppointmentId": $scope.cacheStorageItem.AppointmentId,
        };
        eHnoteSurgeryService.GetASCAdmissionDetails(req).then(function (resp) {
            if (resp.data.status === "Success") {
                $scope.ChecklistFilesObj.SaveTempImagesArray = [];
                if (resp.data.DocumentDetails.length > 0) {
                    $scope.ChecklistFilesObj.SaveTempImagesArray = resp.data.DocumentDetails;
                } else {
                    //    $scope.ChecklistFilesObj.SaveTempImagesArray = [];
                }
                if (resp.data.StatusFlag !== 'B') {
                    $scope.StatusFlag = resp.data.StatusFlag || '';
                }

                if (resp.data.rows.length > 0) {
                    $scope.ChecklistFilesObj.SaveTempImagesArray = resp.data.rows[0].PreOPAdmitFiles || [];

                    $scope.ChecklistFilesObj.SaveTempImagesArray = resp.data.rows[0].PreOPAdmitFiles || [];

                    $scope.AdmissionObj.CopiedPreviousAppointmentId = resp.data.rows[0].CopiedPreviousAppointmentId || null;
                    if ($scope.AdmissionObj.CopiedPreviousAppointmentId !== null) {
                        $scope.GetAppointmentImages($scope.AdmissionObj.CopiedPreviousAppointmentId);
                    };
                    $scope.cacheStorageItem.PreAdmAppointmentId = $scope.cacheStorageItem.PreAdmAppointmentId || 0;
                    if ($scope.cacheStorageItem.PreAdmAppointmentId !== 0) {
                        $scope.GetAppointmentImages($scope.cacheStorageItem.PreAdmAppointmentId);
                    };
                } else {
                    //    $scope.ChecklistFilesObj.SaveTempImagesArray = [];
                }

                /*$scope.ChecklistFilesObj.TempImagesArray = [];*/
                if (resp.data.ClinicalCheckLists.length > 0) {
                    angular.forEach(resp.data.ClinicalCheckLists, function (item) {
                        angular.forEach($scope.AdmissionObj.OrgASCChecklist, function (kitem) {
                            if (item.CheckListCategoryId === 1 && item.CheckListId === kitem.CheckListId) {
                                angular.forEach(kitem.OrganizationCheckListDetails, function (hitem) {
                                    if (item.CheckListId == hitem.CheckListId && item.Value == hitem.Value) {
                                        hitem.IsChecked = true;
                                    }
                                });
                                kitem.Remarks = item.Remarks || "";
                                kitem.ChecklistDate = item.ChecklistDate || "";
                            }
                        });
                    });
                }

                //if (resp.data.AllergyItems.length > 0) {
                //    $scope.AdmissionObj.AllergyItems = angular.copy(resp.data.AllergyItems);
                //}

                //if (resp.data.SystemicHistory.length > 0) {
                //    $scope.AdmissionObj.SystemicHistory = angular.copy(resp.data.SystemicHistory);
                //}

                //if (resp.data.SurgicalHistory.length > 0) {
                //    $scope.AdmissionObj.SurgicalHistory = angular.copy(resp.data.SurgicalHistory);
                //}

                //if (resp.data.CurrentSystemicMedicationList.length > 0) {
                //    $scope.AdmissionObj.CurrentSystemicMedicationsHistory = angular.copy(resp.data.CurrentSystemicMedicationList);
                //}

                //if (resp.data.CurrentEyeMedicationList.length > 0) {
                //    $scope.AdmissionObj.CurrentEyeMedications = angular.copy(resp.data.CurrentEyeMedicationList);
                //}

                if (resp.data.InvestigationsList.length > 0) {
                    $scope.AdmissionObj.InvestigationsList = angular.copy(resp.data.InvestigationsList);
                }

                if (resp.data.Prescription.length > 0) {
                    $scope.AdmissionObj.Prescriptions = angular.copy(resp.data.Prescription);
                }
            }
            if (resp.data.status === "Failure") {
                alertify.error(resp.data.Message);
            }
        }, function (err) {
            console.log(err);
        });
    }
    $scope.formatUSNumber = function (phoneNumberString, Type) {
        $scope.USnumberString = phoneNumberString || "";
        if ($scope.USnumberString != "") {
            console.log($scope.USnumberString);
            const match = phoneNumberString
                .replace(/\D+/g, '')
                .match(/([^\d]*\d[^\d]*){1,10}$/)[0]
            const part1 = match.length > 3 ? `(${match.substring(0, 3)})` : match
            const part2 = match.length > 3 ? ` ${match.substring(3, 6)}` : ''
            const part3 = match.length > 6 ? `-${match.substring(6, 10)}` : ''
            if (Type == "MobileNumber") {
                $scope.AdmissionCheckinObj.PhoneNumber = part1 + part2 + part3;
            }
            if (Type == "AlternateMobileNumber") {
                $scope.AdmissionCheckinObj.AlternatePhoneNumber = part1 + part2 + part3;
            }
        }
    }


    $scope.$on("SummaryNavSubEvent", function (event, data) {
        if (data == 0) {
            $scope.init();
        } else if (data == 1) {
            $scope.ChangeTab(2);
        } else if (data == 2) {
            $scope.ChangeTab(3);
        } else if (data == 3) {
            $scope.ChangeTab(4);
        } else if (data == 4) {
            $scope.ChangeTab(11);
        } else if (data == 5) {
            $scope.ChangeTab(13);
        }

    });

