    $scope.getMasterClinicalVisitTemplates = function (val) {
        var object = {
            "OrganizationId": $scope.HospitalId,
            "SearchText": val,
        };


        return eHnoteSettingsDataService.GetMasterClinicalVisitTemplates(object).then(function (response) {
            if (response.data.count !== 0) {
                if (response.data.rows !== undefined) {
                    return response.data.rows.map(function (item) {
                        return item;
                    });
                }
            }
        });

    };

