                            let OldExternal = $filter("filter")($scope.PcpRefdetails, function (item) {
                                return item.DoctorID == $scope.LogObj.SurgeryList[0].ExternalCoManagerId;
                            });
                            if (OldExternal.length > 0)
                                OldAffecteditem += `${OldAffecteditem ? '\n ' : ''}External CoManager: ${OldExternal[0].FullName}`;
