    $scope.SaveTemplateName = function (val) {

        if (val == 1) {
            $scope.AdmissionObj.ChecklistTemplateName = $scope.AdmissionObj.NurseChecklistTemplateName || "";
        }
        if (val == 5) {
            $scope.AdmissionObj.ChecklistTemplateName = $scope.AdmissionObj.MedicationChecklistTemplateName || "";
        }
        if (val == 6) {
            $scope.AdmissionObj.ChecklistTemplateName = $scope.AdmissionObj.GeneralChecklistTemplateName || "";
        }
        if (val == 17) {
            $scope.AdmissionObj.ChecklistTemplateName = $scope.AdmissionObj.AdmitChecklistTemplateName || "";
        }

        if ($scope.AdmissionObj.ChecklistTemplateName === "") {
            alertify.error("Please enter template name!");
            return false;
        } else {
            let templateReq = {
                "UserId": $scope.UserId,
                "HospitalId": $scope.HospitalId,
                "UserPreOpCheckListTemplateId": 0,
                "TemplateName": $scope.AdmissionObj.ChecklistTemplateName || "",
                "CheckListCategoryId": val,
                "DeleteInd": "N",
                "TemplateDetails": [],
                "RoleId": $scope.RoleId,
                "IsFavorite": false,
            };
            if (val == 1) {
                let ConcernedChecklistArray = $filter('filter')($scope.AdmissionObj.OrgASCChecklist, { 'CheckListCategoryId': 1, 'CheckListSubTypeId': 1 }, true);
                angular.forEach(ConcernedChecklistArray, function (hitem) {
                    let TempArray = $filter('filter')(hitem.OrganizationCheckListDetails, { 'IsChecked': true }) || [];
                    if (TempArray.length > 0) {
                        let obj = {
                            "UserPreOpCheckListTemplateDetailId": 0,
                            "UserPreOpCheckListTemplateId": 0,
                            "CheckListId": hitem.CheckListId,
                            "OrganizationPreOpCheckListId": hitem.OrganizationPreOpCheckListId,
                            "OrganizationPreOpCheckListValueId": TempArray[0].OrganizationPreOpCheckListValueId,
                            "DeleteInd": "N"
                        };
                        templateReq.TemplateDetails.push(obj);
                    } else {
                        let obj = {
                            "UserPreOpCheckListTemplateDetailId": 0,
                            "UserPreOpCheckListTemplateId": 0,
                            "CheckListId": hitem.CheckListId,
                            "OrganizationPreOpCheckListId": hitem.OrganizationPreOpCheckListId,
                            "OrganizationPreOpCheckListValueId": null,
                            "DeleteInd": "N"
                        };
                        templateReq.TemplateDetails.push(obj);
                    }
                    //angular.forEach(hitem, function (item) {
                    //    angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                    //        if (kitem.IsChecked) {
                    //            let obj = {
                    //                "UserPreOpCheckListTemplateDetailId": 0,
                    //                "UserPreOpCheckListTemplateId": 0,
                    //                "CheckListId": item.CheckListId,
                    //                "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                    //                "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                    //                "DeleteInd": "N"
                    //            };
                    //            templateReq.TemplateDetails.push(obj);
                    //        }
                    //    });
                    //});
                });
            } else {
                let ConcernedChecklistArray = $filter('filter')($scope.AdmissionObj.OrgASCChecklist, { 'CheckListCategoryId': val }, true);
                angular.forEach(ConcernedChecklistArray, function (item) {
                    let TempArray = $filter('filter')(item.OrganizationCheckListDetails, { 'IsChecked': true }) || [];
                    if (TempArray.length > 0) {
                        let obj = {
                            "UserPreOpCheckListTemplateDetailId": 0,
                            "UserPreOpCheckListTemplateId": 0,
                            "CheckListId": item.CheckListId,
                            "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                            "OrganizationPreOpCheckListValueId": TempArray[0].OrganizationPreOpCheckListValueId,
                            "DeleteInd": "N"
                        };
                        templateReq.TemplateDetails.push(obj);
                    } else {
                        let obj = {
                            "UserPreOpCheckListTemplateDetailId": 0,
                            "UserPreOpCheckListTemplateId": 0,
                            "CheckListId": item.CheckListId,
                            "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                            "OrganizationPreOpCheckListValueId": null,
                            "DeleteInd": "N"
                        };
                        templateReq.TemplateDetails.push(obj);
                    }
                    //angular.forEach(item.OrganizationCheckListDetails, function (kitem) {
                    //    if (kitem.IsChecked) {
                    //        let obj = {
                    //            "UserPreOpCheckListTemplateDetailId": 0,
                    //            "UserPreOpCheckListTemplateId": 0,
                    //            "CheckListId": item.CheckListId,
                    //            "OrganizationPreOpCheckListId": item.OrganizationPreOpCheckListId,
                    //            "OrganizationPreOpCheckListValueId": kitem.OrganizationPreOpCheckListValueId,
                    //            "DeleteInd": "N"
                    //        };
                    //        templateReq.TemplateDetails.push(obj);
                    //    }
                    //});
                });
            }

            if (templateReq.TemplateDetails.length == 0) {
                alertify.error("Please Add atleast One Check list!");
                return false;

            }
            eHnoteSurgeryService.AddUpdatePreOpCheckListTemplates(templateReq).then(function (resp) {
                if (resp.data.status === "Success") {
                    alertify.success("Template saved successfully!");
                    if (val === 1) {
                        $scope.GetNurseCheckListTemplates();
                        $scope.IsNurseTemplatePopOver = false;
                        $scope.AdmissionObj.NurseChecklistTemplateName = '';
                    }
                    if (val === 5) {
                        $scope.GetMedicineCheckListTemplates();
                        $scope.IsMedicineTemplatePopOver = false;
                        $scope.AdmissionObj.MedicationChecklistTemplateName = '';
                    }
                    if (val === 6) {
                        $scope.GetGeneralCheckListTemplates();
                        $scope.IsGeneralTemplatePopOver = false;
                        $scope.AdmissionObj.GeneralChecklistTemplateName = '';
                    }
                    if (val === 17) {
                        $scope.GetAdmitCheckListTemplates();
                        $scope.IsAdmitTemplatePopOver = false;
                        $scope.AdmissionObj.AdmitChecklistTemplateName = '';
                    }
                }
                if (resp.data.status === "Failure") {
                    alertify.error(resp.data.Message)
                }
            }, function (err) {
                console.log(err);
            });
        }
    };

