    $scope.UpdatePatientData = function () {

        $scope.EditPatientObj = angular.copy($scope.GetEditPatientObj());

        $scope.EditPatientObj.basicDetails = true;
        $scope.EditPatientObj.Race = $scope.cacheStorageItem.RaceName;
        $scope.EditPatientObj.Age = $scope.cacheStorageItem.Age;
        $scope.EditPatientObj.Gender = $scope.cacheStorageItem.Gender;
        $scope.EditPatientObj.BMI = $scope.AdmissionObj.PatientData.BMI;

        $scope.EditPatientObj.PatientVitalsArray.push(VitalsObj);

        //$scope.EditPatientObj.Height = $scope.AdmissionObj.PatientData.Height;
        //$scope.EditPatientObj.Weight = $scope.AdmissionObj.PatientData.Weight;
        //$scope.EditPatientObj.WeightUnitName = $scope.cacheStorageItem.ApptWeightUnit;
        //$scope.EditPatientObj.HeightUnitName = $scope.cacheStorageItem.ApptHeightUnit;

        //if ($scope.AdmissionObj.PatientData.Height != null) {
        //    $scope.EditPatientObj.Height = $scope.AdmissionObj.PatientData.Height;
        //}
        //if ($scope.AdmissionObj.PatientData.Weight != null) {
        //    $scope.EditPatientObj.Weight = $scope.AdmissionObj.PatientData.Weight;
        //}

        //if ($scope.cacheStorageItem.ApptWeightUnit != null) {
        //    $scope.EditPatientObj.WeightUnitName = $scope.cacheStorageItem.ApptWeightUnit;
        //}
        //if ($scope.cacheStorageItem.ApptHeightUnit!= null) {
        //    $scope.EditPatientObj.HeightUnitName = $scope.cacheStorageItem.ApptHeightUnit;
        //}

        //let Heightlist = $filter("filter")($scope.HeightUnits, function (kitem) { return kitem.Unit == $scope.AdmissionObj.PatientData.HeightUnit }, true);
        //if (Heightlist.length > 0) {
        //    $scope.EditPatientObj.HeightUnitId = Heightlist[0].UnitId;
        //}

        //let Weightlist = $filter("filter")($scope.WeightUnits, function (kitem) { return kitem.Unit == $scope.AdmissionObj.PatientData.WeightUnit }, true);
        //if (Weightlist.length > 0) {
        //    $scope.EditPatientObj.WeightUnitId = Weightlist[0].UnitId;
        //}

        var Heightlist = $filter("filter")($scope.HeightUnits, function (kitem) { return kitem.Unit == $scope.AdmissionObj.PatientData.HeightUnit }, true);
        if (Heightlist.length > 0) {
            $scope.EditPatientObj.HeightUnitId = Heightlist[0].UnitId;
        }

        var Weightlist = $filter("filter")($scope.WeightUnits, function (kitem) { return kitem.Unit == $scope.AdmissionObj.PatientData.WeightUnit }, true);
        if (Weightlist.length > 0) {
            $scope.EditPatientObj.WeightUnitId = Weightlist[0].UnitId;
        }

        angular.forEach($scope.EditPatientObj.PatientVitalsArray, function (vitem) {
            angular.forEach(vitem.Vitals, function (item) {
                if (item.VitalId == 1) {
                    item.Value = $scope.AdmissionObj.PatientData.Height || '';
                    item.UnitTypeId = $scope.EditPatientObj.HeightUnitId || 1;
                    /*item.UnitTypeName = $scope.AdmissionObj.PatientData.HeightUnit || 'cm';*/
                    item.UnitTypeName = $scope.EditPatientObj.HeightUnitId == 1 ? 'Ft/Inches' : 'Cms';
                }
                if (item.VitalId == 2) {
                    item.Value = $scope.AdmissionObj.PatientData.Weight || '';
                    item.UnitTypeId = $scope.EditPatientObj.WeightUnitId || 2;
                    item.UnitTypeName = $scope.AdmissionObj.PatientData.WeightUnit || 'lbs';
                }
            });
        });
    }

    $scope.UpdateSurgeryDetails = function () {
        $scope.LogObj.LogArray = [];
        var count = 0;
        angular.forEach($scope.EditPatientObj.PatientVitalsArray, function (vitem) {
            angular.forEach(vitem.Vitals, function (item) {
                if (item.VitalId == 2 && item.UnitTypeId == 2) {
                    item.UnitTypeName = 'lbs';
                    $scope.EditPatientObj.Weight = item.Value || '';
                } else {
                    $scope.EditPatientObj.Height = item.Value || '';
                }
            });
        });
        let obj = {
            "AppointmentID": $scope.cacheStorageItem.AppointmentId,
            "PatientId": $scope.cacheStorageItem.PatientID,
            "UserId": $scope.UserId,
            "AppointmentTypeId": $scope.cacheStorageItem.AppointmentTypeId,
            "PatientVitalsArray": $scope.EditPatientObj.PatientVitalsArray,
            "BMI": $scope.EditPatientObj.BMI,
            "Logs": {},
            //"Height": $scope.EditPatientObj.Height,
            //"Weight": $scope.EditPatientObj.Weight,
            //"HeightUnitId": $scope.EditPatientObj.HeightUnitId || null,
            //"HeightUnitName": $scope.EditPatientObj.HeightUnitName || '',
            //"WeightUnitId": $scope.EditPatientObj.WeightUnitId || '',
            //"WeightUnitName": $scope.EditPatientObj.WeightUnitName || ''
        }
        if ($scope.EditPatientObj.Height != '' || $scope.LogObj.Height != '' || $scope.EditPatientObj.Weight != '' || $scope.LogObj.Weight != '' || $scope.EditPatientObj.BMI !== '' || $scope.LogObj.BMI) {
            let ActionType = ''
            if ($scope.LogObj.Height == '' && $scope.LogObj.Weight == '' && $scope.LogObj.BMI == '') {
                ActionType = 'Added';
            } else {
                ActionType = 'Edited';
            }
            var prevheight = '';
            var newheight = '';
            var prevweight = '';
            var newweight = '';
            var prevBMI = '';
            var newBMI = '';

            if ($scope.LogObj.Height != $scope.EditPatientObj.Height) {

                prevheight = "Height: " + $scope.LogObj.Height + ",";
                newheight = "Height: " + $scope.EditPatientObj.Height + ",";
                count++;
            }
            if ($scope.LogObj.Weight != $scope.EditPatientObj.Weight) {

                prevweight = "Weight: " + $scope.LogObj.Weight + ",";
                newweight = "Weight: " + $scope.EditPatientObj.Weight + ",";
                count++;
            }
            if ($scope.LogObj.BMI != $scope.EditPatientObj.BMI) {

                prevBMI = "BMI: " + $scope.LogObj.BMI;
                newBMI = "BMI: " + $scope.EditPatientObj.BMI;
                count++;
            }

            var OldActionDescription = '';
            var NewActionDescription = '';
            if (prevheight != '' || prevweight != '' || prevBMI != '') {
                OldActionDescription = prevheight + " " + prevweight + " " + prevBMI;
            }
            if (newheight != '' || newweight != '' || newBMI != '') {
                NewActionDescription = newheight + " " + newweight + " " + newBMI;
            }

            if (count !== 0) {
                let obj = {
                    "LogId": 0,
                    "ModuleId": 2,
                    "ModuleName": "ASC",
                    "SubModuleId": 2,
                    "SubModuleName": "Admit",
                    "ScreenType": "BMI",
                    "ActionType": ActionType,
                    "OldActionDescription": OldActionDescription,
                    "NewActionDescription": NewActionDescription,
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                };
                $scope.LogObj.LogArray.push(obj);
            }
        }
        if ($scope.LogObj.LogArray.length > 0) {
            obj.Logs = $scope.LogObj || {};
        }
        eHnoteSurgeryService.UpdatePatientSurgeryData(obj).then(function (resp) {
            if (resp.data.status === "Success") {
                //$scope.PatientDetails.Height = resp.data.Height;
                //$scope.PatientDetails.Weight = resp.data.Weight;
                //$scope.PatientDetails.HeightUnit = resp.data.HeightUnitName;
                //$scope.PatientDetails.WeightUnit = resp.data.WeightUnitName;

                //$scope.cacheStorageItem.ApptHeight = resp.data.Height;
                //$scope.cacheStorageItem.ApptWeight = resp.data.Weight;
                //$scope.cacheStorageItem.ApptHeightUnit = resp.data.HeightUnitName;
                //$scope.cacheStorageItem.ApptWeightUnit = resp.data.WeightUnitName;

                //$scope.AddToCache();

                $scope.GetOTQuickAccessDetails();
                $scope.EditPatientObj = angular.copy($scope.GetEditPatientObj());
            }
        });
    }

