    $scope.OpenVitalsPopUp = function (item, VitalNo) {

        $scope.AdmitVitalInd = true;
        VitalNo = VitalNo || null;
        if (VitalNo == 1) {
            $scope.AdmitVitalInd = false;
        }

        let givenVitalsArray = angular.copy(item.VitalsArray);
        //let DocumentDetails = angular.copy(item.DocumentDetails);

        let DocumentDetails = $filter("filter")(item.DocumentDetails, function (kitem) { return kitem.FileTypeId == 32 }, true);


        let PerformedByArray = $scope.allUserList.filter((x) => x.RoleId == 1 || x.RoleId == 8 || x.RoleId == 30 || x.RoleId == 72 || x.RoleId == 43 || x.RoleId == 18 || x.RoleId == 66 || x.RoleId == 67 || x.RoleId == 16 || x.RoleId == 63 || x.RoleId == 10 || x.RoleId == 38);
        let TypeObj = {
            "TypeId": $scope.AdmitVitalInd ? 7 : 2,
            "TypeName": $scope.AdmitVitalInd ? "Admit Screen" : "Anesthesia PreAdmission",
            "IsComingfrom": "Admin",
        }
        let modalInstance = $uibModal.open({
            "templateUrl": "templates/ASC/ASCVitalsPopUp.html",
            "controller": "USASCVitalsPopUpCtrl",
            "resolve": {
                "VitalsArrayList": function () { return givenVitalsArray || []; },
                "PerformedByArray": function () { return PerformedByArray || []; },
                "DocumentDetails": function () { return DocumentDetails || []; },
                "allUserList": function () { return $scope.allUserList || {}; },
                "UserId": function () { return $scope.UserId || {}; },
                "VitalInd": function () { return $scope.AdmitVitalInd },
                "TypeObj": function () { return TypeObj },
            },
            "windowClass": "modal-full-popup",
            "backdrop": "static",
            //"scope": $scope,
            "keyboard": false
        });

        modalInstance.result.then(function (data) {
            if (data.VitalsArray.length > 0) {
                $scope.AdmissionObj.VitalsArray = angular.copy(data.VitalsArray);
            }

            if ($scope.AdmissionObj.VitalsArray.length > 0) {
                $scope.AdmissionObj.VitalsDisplay = $scope.GetDisplayVitalsArray();
                angular.forEach($scope.AdmissionObj.VitalsArray, function (mainitem, $index) {
                    if (mainitem.DeleteInd == 'N') {
                        let TempFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 11 }, true) || [];
                        if (TempFilter.length > 0) {
                            var tempobj = {
                                "value": TempFilter[0].Value,
                                "UnitTypeName": TempFilter[0].UnitTypeName
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[0].Values.push(tempobj);
                        let pulseFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 12 }, true) || [];
                        if (pulseFilter.length > 0) {
                            var pulseobj = {
                                "value": pulseFilter[0].Value,
                                "UnitTypeName": pulseFilter[0].UnitTypeName
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[1].Values.push(pulseobj);
                        let BpUpFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 4 }, true) || [];
                        let BpLowFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 5 }, true) || [];
                        if (BpUpFilter.length > 0 || BpLowFilter.length > 0) {
                            if (BpUpFilter[0].Value != '' || BpLowFilter[0].Value != '') {
                                var Bpobj = {
                                    "value": BpUpFilter[0].Value + '/' + BpLowFilter[0].Value,
                                    "UnitTypeName": BpUpFilter[0].UnitTypeName
                                }
                            } else {
                                var Bpobj = {
                                    "value": "",
                                    "UnitTypeName": BpUpFilter[0].UnitTypeName
                                }
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[2].Values.push(Bpobj);
                        let RespFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 14 }, true) || [];
                        if (RespFilter.length > 0) {
                            var Respobj = {
                                "value": RespFilter[0].Value,
                                "UnitTypeName": RespFilter[0].UnitTypeName
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[3].Values.push(Respobj);
                        let Spo2Filter = $filter('filter')(mainitem.Vitals, { "VitalId": 15 }, true) || [];
                        if (Spo2Filter.length > 0) {
                            var Spo2obj = {
                                "value": Spo2Filter[0].Value,
                                "UnitTypeName": Spo2Filter[0].UnitTypeName
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[4].Values.push(Spo2obj);
                        let BGLFilter = $filter('filter')(mainitem.Vitals, { "VitalId": 8 }, true) || [];
                        if (BGLFilter.length > 0) {
                            var BGLobj = {
                                "value": BGLFilter[0].Value,
                                "UnitTypeName": BGLFilter[0].UnitTypeName
                            }
                        }
                        $scope.AdmissionObj.VitalsDisplay[5].Values.push(BGLobj);
                        var Time = {
                            "value": $scope.AdmissionObj.VitalsArray[$index].VitalAddTime || "",
                            "UnitTypeName": "",
                        }
                        $scope.AdmissionObj.VitalsDisplay[6].Values.push(Time);
                        var performedBy = {
                            "value": $scope.AdmissionObj.VitalsArray[$index].UserName || "",
                            "UnitTypeName": "",
                        }
                        $scope.AdmissionObj.VitalsDisplay[7].Values.push(performedBy);
                        var Notes = {
                            "value": $scope.AdmissionObj.VitalsArray[$index].VitalRemarks || "",
                            "UnitTypeName": "",
                        }
                        $scope.AdmissionObj.VitalsDisplay[8].Values.push(Notes);
                    }
                });
            }

            if (data.TempImagesArray.length > 0) {
                angular.forEach(data.TempImagesArray, function (sitem, index) {
                    $scope.ChecklistFilesObj.TempImagesArray.push(sitem);
                });
            }
            if (data.DocumentDetails.length > 0) {
                $scope.AdmissionObj.DocumentDetails = data.DocumentDetails || [];
                //angular.forEach(data.DocumentDetails, function (item, index) {
                //    if ($scope.AdmissionObj.DocumentDetails.length > 0) {
                //        var Tempfilter = $filter("filter")($scope.AdmissionObj.DocumentDetails, { "DocumentID": item.DocumentID,'FileTypeId':32}, true) || [];
                //        if (Tempfilter.length == 0) {
                //            $scope.AdmissionObj.DocumentDetails.push(item);
                //        }
                //    } else {
                //        $scope.AdmissionObj.DocumentDetails.push(item);
                //    }
                //});
            } else {
                angular.forEach($scope.AdmissionObj.DocumentDetails, function (ditem, index) {
                    if (ditem.FileTypeId == 32) {
                        ditem.DeleteInd = 'Y';
                    }
                });
                angular.forEach($scope.ChecklistFilesObj.SaveTempImagesArray, function (item, index) {
                    if (item.FileTypeId == 32) {
                        item.DeleteInd = 'Y';
                    }
                });

            }
            //$scope.GetOTQuickAccessDetails();
        }, function (cancel) {

        });
    };

    $scope.faceLiftPopup = function () {
        var type = 1;
        var screentype = "ASC";
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/faceLiftPopup.html",
            "controller": "USFaceSheetPopupCtrl",
            "backdrop": "static",
            "keyboard": false,
            "windowClass": "modal-full-popup",
            "resolve": {
                "allUserList": function () { return $scope.allUserList; },
                "SubTab": function () { return type; },
                "ScreenType": function () { return screentype; },
                "ParentObj": function () { return $scope.ParentObj; },
            }
        });

        $scope.mInstanceAdd.result.then(function (result) {
            $scope.init();
        }, function (cancel) {
        });
    };

