    $scope.Patientdetails = function () {
        let patientId = $scope.cacheStorageItem.PatientID || 0;
        eHnoteAuditServices.getPatientDetailsById(patientId, ongetPatientDetailsSuccess, ongetPatientDetailsError);
        function ongetPatientDetailsSuccess(data) {
            if (data !== undefined) {
                var patientitem = data;

                var PatientMonth = ''
                if (patientitem.Patient[0].AgeInMonths != 0) {
                    var PatientMonth = patientitem.Patient[0].AgeInMonths + 'M';
                }
                $scope.cacheStorageItem.Age = patientitem.Patient[0].AgeInYears + 'Y' + ' ' + PatientMonth;
                $scope.cacheStorageItem.Gender = patientitem.Patient[0].Gender;
                $scope.cacheStorageItem.PatientImageS3URL = patientitem.Patient[0].S3URL;

                $scope.cacheStorageItem.FullName = patientitem.Patient[0].FullName;
                $scope.cacheStorageItem.PatientDisplayID = patientitem.Patient[0].PatientDisplayId;
                $scope.cacheStorageItem.S3URL = patientitem.Patient[0].S3URL || "";
                $scope.cacheStorageItem.DOB = patientitem.Patient[0].DOB;
                $scope.cacheStorageItem.PatientTagList = patientitem.Patient[0].PatientTagList;
                $scope.AddToCache();
            }
        }
        function ongetPatientDetailsError(error) {
            console.log(error);
        }
    }
    $scope.Patientdetails();

