    $scope.AddAccompaniedSigature = function () {

        var obj = {
            "PatientName": $scope.cacheStorageItem.PatientName || '',
            "OrgDigitalSignType": $scope.OrgDigitalSignType || 'Drawing',
            "AccompaniedSign": $scope.AdmissionCheckinObj.AccompaniedSignString || '',
            "AccompaniedSignedDateTime": $scope.AdmissionCheckinObj.AccompaniedSignedDateTime || null,
            "AccompainedName": $scope.AdmissionCheckinObj.AccompainedName || '',
        }
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "AccompaniedBySignacturepopover.html",
            "backdrop": "static",
            "size": "md",
            "resolve": {
                "mainObject": function () { return obj; }
            },
            "windowClass": "zindexpopupConsentSign",
            "keyboard": false,
            "controller": function ($scope, $uibModal, $uibModalInstance, mainObject) {

                var tmr; var resetIsSupported = false;

                $scope.mainObject = mainObject || '';
                $scope.OrgDigitalSignType = $scope.mainObject.OrgDigitalSignType || 'Drawing';

                $scope.signPlusObj = {
                    "AccompaniedSignBy": "Drawing",
                    "AccompaniedSignString": "",
                    "AccompaniedSignedDateTime": null,
                    "AccompainedName": "",
                };

                $scope.signPlusObj.AccompainedName = $scope.mainObject.AccompainedName || '';
                $scope.signPlusObj.AccompaniedSignString = $scope.mainObject.AccompaniedSign || '';
                $scope.signPlusObj.AccompaniedSignedDateTime = $scope.mainObject.AccompaniedSignedDateTime || null;
                $scope.OnSignPatientSignature = function () {
                    $scope.signPlusObj.AccompaniedSignBy = "Topaz";
                    if (IsSigWebInstalled()) {
                        var ctx = document.getElementById('AccompaniedBySign').getContext('2d');
                        SetDisplayPenWidth(5);
                        SetDisplayXSize(1200);
                        SetDisplayYSize(700);
                        SetTabletState(0, tmr);
                        // SetJustifyMode(0);
                        SetJustifyMode(5)
                        ClearTablet();
                        SetEncryptionMode(3);
                        AutoKeyAddData("0000000000000000");
                        SetKeyString("0000000000000000");

                        // SetSigString()
                        if (tmr == null) {
                            tmr = SetTabletState(1, ctx, 50);
                        }
                        else {
                            SetTabletState(0, tmr);
                            tmr = null;
                            tmr = SetTabletState(1, ctx, 50);
                        }

                    } else {
                        alert("Unable to communicate with SigWeb. Please confirm that SigWeb is installed and running on this PC.");
                    }
                };

                $scope.closeuib = function () {

                    $uibModalInstance.close($scope.signPlusObj);
                    // $uibModalInstance.dismiss("cancel");
                };

                function GetResetSupported() {
                    var minSigWebVersionResetSupport = "1.6.4.0";

                    if (isOlderSigWebVersionInstalled(minSigWebVersionResetSupport)) {
                        console.log("Old SigWeb version installed.");
                        return false;
                    }
                    return true;
                }

                function isOlderSigWebVersionInstalled(cmprVer) {
                    var sigWebVer = GetSigWebVersion();
                    if (sigWebVer != "") {
                        return isOlderVersion(cmprVer, sigWebVer);
                    } else {
                        return false;
                    }
                }

                function isOlderVersion(oldVer, newVer) {
                    const oldParts = oldVer.split('.')
                    const newParts = newVer.split('.')
                    for (var i = 0; i < newParts.length; i++) {
                        const a = parseInt(newParts[i]) || 0
                        const b = parseInt(oldParts[i]) || 0
                        if (a < b) return true
                        if (a > b) return false
                    }
                    return false;
                }

                $scope.onLoadSIg = function () {
                    if (IsSigWebInstalled()) {
                        resetIsSupported = GetResetSupported();
                        if (!resetIsSupported) {
                            var sigweb_link = document.createElement("a");
                            sigweb_link.href = "https://www.topazsystems.com/software/sigweb.exe";
                            sigweb_link.innerHTML = "https://www.topazsystems.com/software/sigweb.exe";

                            var note = document.getElementById("sigWebVrsnNote");
                            note.innerHTML = "There is a newer version of SigWeb available here: ";
                            note.appendChild(sigweb_link);
                        }

                        //$scope.OnSignPatientSignature();
                    }
                    else {
                        alert("Unable to communicate with SigWeb. Please confirm that SigWeb is installed and running on this PC.");
                    }
                }
                $scope.onLoadSIg();

                $scope.SaveAccompaniedDrawSign = function (savetype) {
                    if ($scope.signPlusObj.AccompaniedSignBy == "Topaz") {
                        if (NumberOfTabletPoints() == 0) {
                            alertify.error("Please add Signature");
                            return false;
                        }
                        else {
                            SetTabletState(0, tmr);
                            var CryptoData = "";
                            CryptoData = "This represents sample data the signer reads and is agreeing to when signing.";
                            CryptoData = CryptoData + "Concatenate all this data into a single variable.";
                            AutoKeyAddANSIData(CryptoData);
                            SetEncryptionMode(2);

                            SetSigCompressionMode(2);



                            SetImageXSize(1200);
                            SetImageYSize(800);
                            SetImagePenWidth(10);

                            GetSigImageB64(SignedImageCallback);
                            function SignedImageCallback(str) {
                                var convertedSignatureObj = "data:image/png;base64," + str;
                                $scope.signPlusObj.AccompaniedSignString = convertedSignatureObj;
                                $scope.signPlusObj.AccompaniedSignedDateTime = $filter('date')(new Date(), "MM-dd-yyyy hh:mm a");

                                alertify.success("Signature added Successfully ");
                                if (savetype == "complete") {
                                    $uibModalInstance.close($scope.signPlusObj);
                                }
                            }
                        }

                    } else {
                        var canvas = document.getElementById('AccompaniedBySign');
                        var sign = canvas.toDataURL();
                        //if (sign == 'data:image/png;base64,') {
                        if (sign == 'data:image/png;base64,') {
                            alertify.error("Please sign to continue");
                            return false;
                        } else {
                            $scope.signPlusObj.AccompaniedSignString = sign || '';
                            $scope.signPlusObj.AccompaniedSignedDateTime = $filter('date')(new Date(), "MM-dd-yyyy hh:mm a");
                        }

                        alertify.success("Signature added Successfully ");
                        if (savetype == "complete") {
                            $uibModalInstance.close($scope.signPlusObj);
                        }
                    }
                }

                $scope.OnClearAccompaniedBySignature = function () {
                    ClearTablet();
                    var canvas = document.getElementById('AccompaniedBySign');
                    var context = canvas.getContext('2d');
                    context.clearRect(0, 0, canvas.width, canvas.height);
                    $scope.signPlusObj.AccompaniedSignBy = 'Drawing';
                    $scope.signPlusObj.AccompaniedSignString = '';
                    $scope.signPlusObj.AccompainedName = '';
                }

                $uibModalInstance.rendered.then(function () {
                    if ($scope.mainObject.AccompaniedSign != '') {
                        var canvas = document.getElementById("AccompaniedBySign");
                        var ctx = canvas.getContext("2d");
                        ctx.clearRect(0, 0, canvas.width, canvas.height);
                        var image = new Image();
                        image.onload = function () {
                            ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
                        };
                        image.src = $scope.mainObject.AccompaniedSign;
                    }
                });
            }
        });
        $scope.mInstanceAdd.result.then(function (result) {

            $scope.AdmissionCheckinObj.IsAccompaniedSignDone = false;
            $scope.AdmissionCheckinObj.AccompaniedSignString = result.AccompaniedSignString || '';
            if ($scope.AdmissionCheckinObj.AccompaniedSignString != '') {
                $scope.AdmissionCheckinObj.AccompaniedSignedDateTime = result.AccompaniedSignedDateTime || null;
                $scope.AdmissionCheckinObj.IsAccompaniedSignDone = true;
                $scope.AdmissionCheckinObj.AccompainedName = result.AccompainedName || "";
                genPatientImg(result.AccompaniedSignString);
            }

        }, function (cancel) {
        });
    };

    function genPatientImg(basestr) {
        var canvas = document.getElementById("SE_AccompaniedBySign");
        var ctx = canvas.getContext("2d");
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        var image = new Image();
        image.onload = function () {
            ctx.drawImage(image, 0, 0, canvas.width, canvas.height);
        };

        image.src = basestr;
    }

    $scope.clearSign = function (id) {
        var canvas = document.getElementById(id);
        var context = canvas.getContext('2d');
        context.clearRect(0, 0, canvas.width, canvas.height);

        $scope.AdmissionCheckinObj.AccompaniedSignString = '';
        $scope.AdmissionCheckinObj.AccompaniedSignedDateTime = null;
        $scope.AdmissionCheckinObj.IsAccompaniedSignDone = false;
        $scope.AdmissionCheckinObj.AccompainedName = '';
    }



