    $scope.GetAppointmentImages = function (Id) {
        var AppointmentId = Id || 0;
        var req = {
            "AppointmentId": AppointmentId
        };
        eHnoteSurgeryService.GetAppointmentImagesData(req).then(function (resp) {
            if (resp.data.status === "Success") {
                if (resp.data.rows.length > 0) {
                    $scope.AdmissionObj.AppointmentImagesArray = angular.copy(resp.data.rows);
                } else {
                    $scope.AdmissionObj.AppointmentImagesArray = [];
                }
                if ($scope.AdmissionObj.AppointmentImagesArray.length > 0) {
                    angular.forEach($scope.AdmissionObj.AppointmentImagesArray, function (item) {
                        if (item.FileTypeId == 32 || item.FileTypeId == 33) {
                            $scope.ChecklistFilesObj.SaveTempImagesArray.push(item);
                            $scope.AdmissionObj.DocumentDetails.push(item);
                        };
                    });
                };
            }
        });
    };

