    $scope.GetValidateUserPassword = function () {

        $scope.AdmissionObj.OrderedBy = $scope.AdmissionObj.OrderedBy || null;
        if ($scope.AdmissionObj.OrderedBy == null) {
            alertify.error("Please Select ReviewedBy");
            return false;
        }
        $scope.AdmissionObj.OrderedByPassword = $scope.AdmissionObj.OrderedByPassword || '';
        if ($scope.AdmissionObj.OrderedByPassword == '') {
            alertify.error("Please Enter Password");
            return false;
        }
        let reqObj = {
            "Password": $scope.AdmissionObj.OrderedByPassword,
            "UserId": $scope.UserId,
            "ReviewedBy": $scope.AdmissionObj.OrderedBy,
            "OrganizationId": $scope.HospitalId
        };
        eHnoteSurgeryService.GetUserValidatePassword(reqObj).then(function (resp) {
            if (resp.data.status === "Success") {
                alertify.success("Successfully Validated!");
                $scope.AdmissionObj.IsOrderedByReviewed = true;
                //$scope.AdmissionObj.OrderedByDateTime = $filter("date")(new Date(), "MM-dd-yyyy hh:mm a");
                let Admissiondatetime = $scope.cacheStorageItem.Admissiondatetime || null;
                $scope.AdmissionObj.OrderedByDateTime = $filter("date")(new Date(), "MM-dd-yyyy hh:mm a") || null;
                if (Admissiondatetime) {
                    $scope.AdmissionObj.OrderedByDateTime = $filter('date')(Admissiondatetime, "MM-dd-yyyy hh:mm a") || null;
                }

                angular.forEach($scope.SurgeonArray, function (subitem) {
                    if (subitem.DoctorID == $scope.AdmissionObj.OrderedBy) {
                        $scope.AdmissionObj.OrderedByName = subitem.UserFullName;
                        $scope.AdmissionObj.OrderedByLicenseNumber = subitem.LicenseNumber;
                    }
                });

            } else {
                alertify.error("Invalid Password!");
            }
        }, function (err) {
            alertify.error("Fetching data failed!");

        });
    };
    $scope.EditOrderedBy = function () {
        $scope.AdmissionObj.IsshowOrderededit = true;
        $scope.AdmissionObj.IsOrderedByReviewed = false;
    }
    $scope.navtoconformation = function (val) {
        if ($scope.AdmissionObj.IsOrderedByReviewed == false && $scope.AdmissionObj.OrderedBy !== null && $scope.AdmissionObj.OrderedByPassword !== '') {
            let mInstanceAdd = $uibModal.open({
                "templateUrl": "AdmitOrderedbyConfirmation.html",
                "size": "md",
                "backdrop": "static",
                "keyboard": false,
                "scope": $scope,
                "windowClass": "",
                "controller": function ($scope, $uibModal, $uibModalInstance) {
                    $scope.closeuibpopup = function () {
                        $uibModalInstance.dismiss("cancel");
                    }

                    $scope.Admitwithoutvalidating = function () {
                        $scope.saveFinalAdmitData(val);
                        $uibModalInstance.close();
                    }
                    $scope.ValidateandAdmit = function () {
                        $scope.AdmissionObj.OrderedBy = $scope.AdmissionObj.OrderedBy || null;
                        if ($scope.AdmissionObj.OrderedBy == null) {
                            alertify.error("Please Select ReviewedBy");
                            return false;
                        }
                        $scope.AdmissionObj.OrderedByPassword = $scope.AdmissionObj.OrderedByPassword || '';
                        if ($scope.AdmissionObj.OrderedByPassword == '') {
                            alertify.error("Please Enter Password");
                            return false;
                        }
                        let reqObj = {
                            "Password": $scope.AdmissionObj.OrderedByPassword,
                            "UserId": $scope.UserId,
                            "ReviewedBy": $scope.AdmissionObj.OrderedBy,
                            "OrganizationId": $scope.HospitalId
                        };
                        eHnoteSurgeryService.GetUserValidatePassword(reqObj).then(function (resp) {
                            if (resp.data.status === "Success") {
                                alertify.success("Successfully Validated!");
                                $scope.AdmissionObj.IsOrderedByReviewed = true;
                                $scope.AdmissionObj.OrderedByDateTime = $filter("date")(new Date(), "MM-dd-yyyy hh:mm a");


                                angular.forEach($scope.SurgeonArray, function (subitem) {
                                    if (subitem.DoctorID == $scope.AdmissionObj.OrderedBy) {
                                        $scope.AdmissionObj.OrderedByName = subitem.UserFullName;
                                        $scope.AdmissionObj.OrderedByLicenseNumber = subitem.LicenseNumber;
                                    }
                                });

                                $scope.saveFinalAdmitData(val);
                                $uibModalInstance.close();
                            } else {
                                alertify.error("Invalid Password!");
                            }
                        }, function (err) {
                            alertify.error("Fetching data failed!");

                        });
                    }
                }
            });
        } else {
            $scope.saveFinalAdmitData(val);
        }
    };
