    /* Loads the favourites, order templates and dosage master data the
       Pre-Op Surgeon Orders section needs. Safe to call more than once. */
    $scope.GetAdmitPreOpSurgeonOrdersMasterData = function () {
        var templateReq = {
            "HospitalId": $scope.HospitalId,
            "UserId": $scope.UserId,
            "ScreenTypeId": 0,
            "PageSize": 100,
            "SearchText": '',
            "PageNumber": 1
        };
        $q.all([
            eHnoteSurgeryService.GetOrganizationPreOpMedications($scope.HospitalId),
            eHnoteSurgeryService.GetAscUserOrderTemplates(templateReq),
            eHnoteDiagnosisDataServices.GetMedicineDosageFieldsMasterData()
        ]).then(function (resp) {
            if (resp[0] && resp[0].data && resp[0].data.status === "Success") {
                angular.forEach(resp[0].data.rows, function (item) {
                    item.AscMedicationId = 0;
                    item.IsChecked = false;
                    item.DropTimings = [{ "MedicationTime": "" }, { "MedicationTime": "" }];
                });
                $scope.MasterDilationMedications = angular.copy($filter('filter')(resp[0].data.rows, { "MedTypeId": 2 }, true)) || [];
            }
            if (resp[1] && resp[1].data) {
                $scope.UserOrderList = resp[1].data.rows || [];
            }
            if (resp[2] && resp[2].data && resp[2].data.status === "Success") {
                $scope.doseArray = resp[2].data.doseArray || [];
                $scope.doseOtherArray = resp[2].data.doseOtherArray || [];
                $scope.doseUnitArray = resp[2].data.doseUnitArray || [];
                $scope.actionArray = resp[2].data.actionArray || [];
                $scope.routeArray = resp[2].data.routeArray || [];
                $scope.frequencyArray = resp[2].data.frequencyArray || [];
                $scope.quantityUnitArray = resp[2].data.quantityUnitArray || [];
            }
        }, function (err) {
            console.log(err);
        });
    };
    $scope.GetAdmitPreOpSurgeonOrdersMasterData();

    /* Standing before the admission is saved, Live afterwards (same rule the All Orders popup applies when it opens) */
    $scope.SetAdmitOrderType = function () {
        if (($scope.cacheStorageItem.AdmissionId || 0) == 0) {
            OrderTypeId = 1;
            OrderTypeName = "Standing Medications(Pre Surgery)";
        } else {
            OrderTypeId = 2;
            OrderTypeName = "Live Medications";
        }
    };

    /* Pre-Op Surgeon orders (MedTypeId 2) saved from Admit belong to the Pre-OP screen (ScreenTypeId 4).
       Every order saved, reloaded and updated here uses this one value, so an update matches the saved row
       instead of inserting a duplicate. */
    var ADMIT_SURGEON_SCREEN = {
        "MedTypeId": 2,
        "MedTypeName": "Dilation Medication",
        "ScreenType": "PreOp",
        "ScreenTypeId": 4,
        "ScreenTypeName": "Pre-OP"
    };
    /* Order templates are shared with the All Orders popup and stay on the Pre-OP screen */
    var ADMIT_SURGEON_TEMPLATE_SCREEN = {
        "ScreenType": "PreOp",
        "ScreenTypeId": 4,
        "ScreenTypeName": "Pre-OP"
    };

    /* Every Pre-Op Surgeon order in OrderDetails carries OrderTypeId / OrderTypeName
       (1 "Standing Medications(Pre Surgery)" / 2 "Live Medications") and, because it is MedTypeId 2,
       ScreenType "PreOp" / ScreenTypeId 4 / ScreenTypeName "Pre-OP".
       An order keeps its own type once it has one; otherwise it takes the current Standing/Live type.
       Its medications carry the same OrderTypeId / OrderTypeName as the order. */
    $scope.SetAdmitSurgeonOrderTypeFields = function (Mitem) {
        Mitem.OrderTypeId = Number(Mitem.OrderTypeId) == 2 ? 2 : (Number(Mitem.OrderTypeId) == 1 ? 1 : OrderTypeId);
        Mitem.OrderTypeName = Mitem.OrderTypeId == 2 ? "Live Medications" : "Standing Medications(Pre Surgery)";
        Mitem.MedTypeId = ADMIT_SURGEON_SCREEN.MedTypeId;
        Mitem.MedTypeName = ADMIT_SURGEON_SCREEN.MedTypeName;
        Mitem.ScreenType = ADMIT_SURGEON_SCREEN.ScreenType;
        Mitem.ScreenTypeId = ADMIT_SURGEON_SCREEN.ScreenTypeId;
        Mitem.ScreenTypeName = ADMIT_SURGEON_SCREEN.ScreenTypeName;

        angular.forEach(Mitem.DilationMedications || [], function (item) {
            item.OrderTypeId = Mitem.OrderTypeId;
            item.OrderTypeName = Mitem.OrderTypeName;
        });
        return Mitem;
    };

    function isActive(row) {
        return row && row.DeleteInd !== 'Y';
    }

    /* Times come back from the database as "15:05:00", "03:05:00.0000000" or "1900-01-01T15:05:00";
       the screen works with "hh:mm AM/PM" (what the clock fills in) */
    function normalizeAdmitOrderTime(value) {
        if (value === null || value === undefined) {
            return '';
        }
        value = String(value).trim();
        if (value === '') {
            return '';
        }
        let match = value.match(/(?:^|T|\s)(\d{1,2}):(\d{2})(?::\d{2}(?:\.\d+)?)?\s*(AM|PM)?$/i);
        if (!match) {
            return value;
        }
        let hours = Number(match[1]);
        let meridian = match[3] ? match[3].toUpperCase() : '';
        if (!meridian) {
            meridian = hours >= 12 ? 'PM' : 'AM';
            hours = hours % 12 || 12;
        }
        return ('0' + hours).slice(-2) + ':' + match[2] + ' ' + meridian;
    }

    /* Reads a column from a database row whatever its casing (OrderTypeId / OrderTypeID / ordertypeid),
       trying each alias in turn; returns undefined when none is present. */
    function readAdmitField(row) {
        if (!row) {
            return undefined;
        }
        let keys = Object.keys(row);
        for (let i = 1; i < arguments.length; i++) {
            let wanted = String(arguments[i]).toLowerCase();
            let key = keys.filter(function (k) { return k.toLowerCase() === wanted; })[0];
            if (key !== undefined && row[key] !== null && row[key] !== '') {
                return row[key];
            }
        }
        return undefined;
    }

    /* the screen compares against 'Done' / 'NotDone' */
    function normalizeAdmitOrderStatus(status) {
        let key = String(status || '').replace(/[\s_-]/g, '').toLowerCase();
        if (key === 'done') {
            return 'Done';
        }
        if (key === 'notdone') {
            return 'NotDone';
        }
        return status || '';
    }

    function findAdmitUser(doctorId) {
        if (!doctorId) {
            return null;
        }
        return ($scope.allUserList || []).filter(function (u) { return u.DoctorID == doctorId; })[0] || null;
    }

    /* The Given By dropdowns list nurses (RoleId 8) only. A saved Given By outside that list, or returned as a
       different type, would leave the dropdown blank - add the option and use the option's id. */
    function ensureAdmitGivenByOption(givenBy, givenByName) {
        if (!givenBy) {
            return null;
        }
        $scope.MedicationGivenByNurseArray = $scope.MedicationGivenByNurseArray || [];
        let option = $scope.MedicationGivenByNurseArray.filter(function (u) { return u.DoctorID == givenBy; })[0];
        if (!option) {
            let user = findAdmitUser(givenBy);
            option = {
                "DoctorID": user ? user.DoctorID : givenBy,
                "FullName": (user && user.FullName) || givenByName || '',
                "LicenseNumber": (user && user.LicenseNumber) || '',
                "RoleId": user ? user.RoleId : null
            };
            $scope.MedicationGivenByNurseArray.push(option);
        }
        return option.DoctorID;
    }

    /* template dropdown - a plain {'MedTypeId':2} filter would also match 12, 20, ... */
    $scope.IsAdmitSurgeonTemplate = function (template) {
        return template && template.MedTypeId == 2;
    };

    function getAdmitSurgeonOrders() {
        return ($scope.AdmissionObj.OrderDetails || []).filter(function (oitem) {
            return oitem.MedTypeId == 2;
        });
    }

    /* Time / Given By of Done custom orders, by GeneralOrderId and by name + Standing/Live.
       GetASCAdmissionDetails can return a Done custom order without them; the Summary and the
       Add screen then fall back to what was entered (last save) or loaded (quick access). */
    let admitGeneralOrderValues = { byId: {}, byName: {} };
    function admitGeneralOrderNameKey(gitem, orderTypeId) {
        return (Number(orderTypeId) || 0) + '|' + String(gitem.MedicineName || '').trim().toLowerCase();
    }
    function mergeAdmitGeneralOrderValues(store, key, gitem) {
        let known = store[key] || {};
        store[key] = {
            "MedicationTime": normalizeAdmitOrderTime(readAdmitField(gitem, 'MedicationTime')) || known.MedicationTime || '',
            "GivenBy": readAdmitField(gitem, 'GivenBy', 'GivenById') || known.GivenBy || null,
            "GivenByname": readAdmitField(gitem, 'GivenByname', 'GivenByName') || known.GivenByname || ''
        };
    }
    $scope.RememberAdmitGeneralOrderValues = function () {
        angular.forEach(getAdmitSurgeonOrders(), function (Mitem) {
            angular.forEach(Mitem.GeneralOrders || [], function (gitem) {
                if (!isActive(gitem) || normalizeAdmitOrderStatus(gitem.Status) !== 'Done') {
                    return;
                }
                if (!readAdmitField(gitem, 'MedicationTime') && !readAdmitField(gitem, 'GivenBy', 'GivenById')) {
                    return;
                }
                if (Number(gitem.GeneralOrderId) > 0) {
                    mergeAdmitGeneralOrderValues(admitGeneralOrderValues.byId, String(gitem.GeneralOrderId), gitem);
                }
                mergeAdmitGeneralOrderValues(admitGeneralOrderValues.byName, admitGeneralOrderNameKey(gitem, Mitem.OrderTypeId), gitem);
                mergeAdmitGeneralOrderValues(admitGeneralOrderValues.byName, admitGeneralOrderNameKey(gitem, 0), gitem);
            });
        });
    };
    function findAdmitGeneralOrderValues(gitem, orderTypeId) {
        return (Number(gitem.GeneralOrderId) > 0 && admitGeneralOrderValues.byId[String(gitem.GeneralOrderId)]) ||
            admitGeneralOrderValues.byName[admitGeneralOrderNameKey(gitem, orderTypeId)] ||
            admitGeneralOrderValues.byName[admitGeneralOrderNameKey(gitem, 0)] || null;
    }

    /* The open (not signed) MedTypeId 2 order for the current Standing/Live type. New medications,
       custom orders, favourites and template items all go into this one order, so the same order
       row is reused instead of a new one being created for every add. A saved order that was emptied
       (DeleteInd 'Y') is revived rather than inserting another. */
    $scope.GetAdmitSurgeonOrderHeader = function () {
        let openOrders = getAdmitSurgeonOrders().filter(function (oitem) {
            /* a saved order whose Standing/Live type was not returned is reused rather than adding another order */
            return !oitem.IsOrderReviewed && (oitem.OrderTypeId == OrderTypeId || oitem.IsOrderTypeInferred);
        });
        let header = openOrders.filter(function (oitem) { return isActive(oitem) && oitem.OrderTypeId == OrderTypeId; })[0] ||
            openOrders.filter(isActive)[0] || openOrders[0];
        if (header) {
            header.DeleteInd = 'N';
            header.DilationMedications = header.DilationMedications || [];
            header.PreOpMedications = header.PreOpMedications || [];
            header.GeneralOrders = header.GeneralOrders || [];
            return $scope.SetAdmitSurgeonOrderTypeFields(header);
        }
        header = {
            "UserOrderId": 0,
            "UserId": $scope.UserId,
            "DeleteInd": "N",
            "ReviewedBy": null,
            "ReviewedByName": '',
            "IsOrderReviewed": false,
            "ReviewedByDateTime": null,
            "ReviewedByPassword": '',
            "UserType": "Nurse",
            "ScreenType": ADMIT_SURGEON_SCREEN.ScreenType,
            "ScreenTypeId": ADMIT_SURGEON_SCREEN.ScreenTypeId,
            "ScreenTypeName": ADMIT_SURGEON_SCREEN.ScreenTypeName,
            "MedTypeId": ADMIT_SURGEON_SCREEN.MedTypeId,
            "MedTypeName": ADMIT_SURGEON_SCREEN.MedTypeName,
            "DilationMedications": [],
            "PreOpMedications": [],
            "GeneralOrders": [],
            "OrderTypeId": OrderTypeId,
            "OrderTypeName": OrderTypeName
        };
        $scope.SetAdmitSurgeonOrderTypeFields(header);
        $scope.AdmissionObj.OrderDetails.push(header);
        return header;
    };

    /* An order with no active medications / custom orders: an unsaved one is dropped, a saved one is marked deleted */
    $scope.CleanupAdmitSurgeonOrderHeaders = function () {
        $scope.AdmissionObj.OrderDetails = ($scope.AdmissionObj.OrderDetails || []).filter(function (Mitem) {
            if (Mitem.MedTypeId != 2) {
                return true;
            }
            let hasItems = (Mitem.DilationMedications || []).some(isActive) || (Mitem.GeneralOrders || []).some(isActive);
            if (hasItems) {
                return true;
            }
            if ((Mitem.UserOrderId || 0) == 0) {
                return false;
            }
            Mitem.DeleteInd = 'Y';
            return true;
        });
    };

    /* Copying / clearing a connected Pre-Admission appointment replaces the pre-admission orders only -
       the Pre-Op Surgeon Orders (MedTypeId 2) entered on Admit are kept as they are */
    $scope.KeepAdmitSurgeonOrders = function () {
        return getAdmitSurgeonOrders();
    };

    /* Admit print: active orders only (deleted rows removed), Standing before Live */
    $scope.GetAdmitSurgeonOrdersForPrint = function () {
        let orders = angular.copy(getAdmitSurgeonOrders().filter(isActive));
        orders = orders.map(function (Mitem) {
            Mitem.DilationMedications = (Mitem.DilationMedications || []).filter(isActive).map(function (item) {
                item.OrderDescription = item.OrderDescription || item.MedicationName || '';
                item.MedicationNotes = item.MedicationNotes || '';
                item.DropTimings = (item.DropTimings || []).filter(isActive).map(function (kitem) {
                    kitem.MedicationDosage = kitem.MedicationDosage || '';
                    kitem.MedicationTime = kitem.MedicationTime || '';
                    kitem.GivenByname = kitem.GivenByname || '';
                    kitem.LicenseNumber = kitem.LicenseNumber || '';
                    kitem.Remarks = kitem.Remarks || '';
                    return kitem;
                });
                return item;
            });
            Mitem.GeneralOrders = (Mitem.GeneralOrders || []).filter(isActive).map(function (gitem) {
                gitem.MedicationTime = gitem.Status === 'Done' ? (gitem.MedicationTime || '') : '';
                gitem.GivenByname = gitem.Status === 'Done' ? (gitem.GivenByname || '') : '';
                gitem.LicenseNumber = gitem.Status === 'Done' ? (gitem.LicenseNumber || '') : '';
                gitem.Status = gitem.Status || '';
                return gitem;
            });
            Mitem.ReviewedByName = Mitem.IsOrderReviewed ? (Mitem.ReviewedByName || '') : '';
            return Mitem;
        }).filter(function (Mitem) {
            return Mitem.DilationMedications.length > 0 || Mitem.GeneralOrders.length > 0;
        });
        return orders.sort(function (a, b) {
            return (Number(a.OrderTypeId) || 1) - (Number(b.OrderTypeId) || 1);
        });
    };

    /* Summary: every active medication / custom order / sign-off for Standing (1) or Live (2), across that type's orders */
    function getAdmitSummaryOrders(orderTypeId) {
        return getAdmitSurgeonOrders().filter(function (Mitem) {
            return isActive(Mitem) && Mitem.OrderTypeId == orderTypeId;
        });
    }
    $scope.GetAdmitSummaryMedications = function (orderTypeId) {
        let list = [];
        angular.forEach(getAdmitSummaryOrders(orderTypeId), function (Mitem) {
            list = list.concat((Mitem.DilationMedications || []).filter(isActive));
        });
        return list;
    };
    $scope.GetAdmitSummaryCustomOrders = function (orderTypeId) {
        let list = [];
        angular.forEach(getAdmitSummaryOrders(orderTypeId), function (Mitem) {
            list = list.concat((Mitem.GeneralOrders || []).filter(isActive));
        });
        return list;
    };
    $scope.GetAdmitSummarySigners = function (orderTypeId) {
        return getAdmitSummaryOrders(orderTypeId).filter(function (Mitem) {
            let hasItems = (Mitem.DilationMedications || []).some(isActive) || (Mitem.GeneralOrders || []).some(isActive);
            return hasItems && Mitem.IsOrderReviewed && Mitem.ReviewedBy != null;
        });
    };

    /* Summary: true when a Standing/Live surgeon order has an active medication or custom order */
    $scope.HasAdmitSurgeonOrderItems = function (orderTypeId) {
        return getAdmitSurgeonOrders().filter(isActive).some(function (Mitem) {
            if (orderTypeId && Mitem.OrderTypeId != orderTypeId) {
                return false;
            }
            return (Mitem.DilationMedications || []).some(isActive) || (Mitem.GeneralOrders || []).some(isActive);
        });
    };

    $scope.IsAdmitSurgeonMedicationAdded = function (medicineId) {
        return getAdmitSurgeonOrders().filter(isActive).some(function (Mitem) {
            return (Mitem.DilationMedications || []).some(function (x) {
                return isActive(x) && x.MedicineId == medicineId;
            });
        });
    };

    $scope.IsAdmitCustomOrderAdded = function (orderName) {
        let name = (orderName || '').trim().toLowerCase();
        return getAdmitSurgeonOrders().filter(isActive).some(function (Mitem) {
            return (Mitem.GeneralOrders || []).some(function (x) {
                return isActive(x) && (x.MedicineName || '').trim().toLowerCase() === name;
            });
        });
    };

    /* "No medications have been administered" can only be ticked while no medication is ordered */
    $scope.RefreshAdmitSurgeonOrdersCheckbox = function () {
        let hasMedication = getAdmitSurgeonOrders().filter(isActive).some(function (Mitem) {
            return (Mitem.DilationMedications || []).some(isActive);
        });
        $scope.AdmitPreOpObj.DisableSurgeonordersCheck = hasMedication;
        if (hasMedication) {
            $scope.AdmitPreOpObj.IsSurgeonOrdersTimeChecked = false;
        }
    };

    /* Audit log payload for the order template / favourite services - keeps the Admit LogObj untouched */
    function buildAdmitOrderLogs(logArray) {
        return {
            "UserId": $scope.UserId || null,
            "OrganizationId": $scope.HospitalId || null,
            "AppointmentId": $scope.cacheStorageItem.AppointmentId || null,
            "PatientId": $scope.cacheStorageItem.PatientID || null,
            "LogArray": logArray || []
        };
    }

    /* Runs before any Admit save confirmation, and again inside saveFinalAdmitData */
    $scope.ValidateAdmitSurgeonOrders = function () {
        /* the section is hidden without the AdmitOrders right, so the user could not correct anything */
        if (!$scope.UserAccessRights.AllAccessRights.AdmitOrders) {
            return true;
        }
        /* a medication still open in the edit form is saved with the Admit Update - no alert */
        if ($scope.AdmitDilationMedicationObj.EditIndex >= 0) {
            $scope.ApplyAdmitMedicationEdit();
        }
        let missingReview = 0, missingTime = 0, missingGivenBy = 0, missingGeneralGivenBy = 0, notValidated = 0, notValidatedGeneral = 0;
        angular.forEach(getAdmitSurgeonOrders().filter(isActive), function (Mitem) {
            let medications = (Mitem.DilationMedications || []).filter(isActive);
            let generalOrders = (Mitem.GeneralOrders || []).filter(isActive);
            if (medications.length == 0 && generalOrders.length == 0) {
                return;
            }
            if (Mitem.ReviewedBy && !Mitem.IsOrderReviewed) {
                missingReview++;
            }
            angular.forEach(medications, function (item) {
                angular.forEach((item.DropTimings || []).filter(isActive), function (kitem) {
                    if (!kitem.MedicationTime) {
                        missingTime++;
                    }
                    if (!kitem.GivenBy) {
                        missingGivenBy++;
                    }
                });
                /* Task 13 - every timing must be validated with the Given By passcode before saving */
                notValidated += DropTimingGivenByService.GetNotValidatedCount(item.DropTimings);
            });
            angular.forEach(generalOrders, function (gitem) {
                if (gitem.Status == 'Done' && !gitem.GivenBy) {
                    missingGeneralGivenBy++;
                }
            });
            /* Task 13 - a custom order marked Done needs the Given By passcode as well */
            notValidatedGeneral += DropTimingGivenByService.GetNotValidatedGeneralOrdersCount(generalOrders);
        });
        if (missingReview !== 0) {
            alertify.error("Please validate the Reviewed by password for Pre-Op Surgeon Orders!");
            return false;
        }
        if (missingTime !== 0) {
            alertify.error("Please enter time for Medications!");
            return false;
        }
        if (missingGivenBy !== 0) {
            alertify.error("Please select Givenby for Medications!");
            return false;
        }
        if (notValidated !== 0) {
            alertify.error("Please validate Given By password for Medications!");
            return false;
        }
        if (missingGeneralGivenBy !== 0) {
            alertify.error("Please select Givenby for General Orders!");
            return false;
        }
        if (notValidatedGeneral !== 0) {
            alertify.error("Please validate Given By password for Custom Orders!");
            return false;
        }
        return true;
    };

    /* Pre-Op Surgeon Orders saved from Admit (Dilation Medications + Custom Orders) come back in
       GetASCAdmissionDetails.OrderDetails. Once the admission exists they replace the MedTypeId 2
       orders taken from GetOTQuickAccessDetails, so the Summary and the Add screen show the saved
       rows with their identity columns (UserOrderId / AscMedicationId / DropTimingId / GeneralOrderId).
       Admit Save posts those ids back, so existing records are updated instead of inserted again. */
    $scope.ApplyAdmitSurgeonOrders = function (admissionData) {
        admissionData = admissionData || {};
        $scope.AdmissionObj.OrderDetails = $scope.AdmissionObj.OrderDetails || [];
        /* init() runs again after every save - keep Standing/Live in step with the saved admission */
        $scope.SetAdmitOrderType();

        /* AllOrdersReviewed and the add handlers walk these arrays on every order */
        angular.forEach($scope.AdmissionObj.OrderDetails, function (oitem) {
            oitem.DilationMedications = oitem.DilationMedications || [];
            oitem.PreOpMedications = oitem.PreOpMedications || [];
            oitem.GeneralOrders = oitem.GeneralOrders || [];
        });

        let responseOrders = admissionData.OrderDetails || [];
        if (angular.isString(responseOrders)) {
            try { responseOrders = JSON.parse(responseOrders) || []; } catch (e) { responseOrders = []; }
        }
        if (!angular.isArray(responseOrders)) {
            responseOrders = [];
        }
        let savedOrders = responseOrders.filter(function (oitem) {
            if (!oitem) {
                return false;
            }
            if (oitem.MedTypeId != null && oitem.MedTypeId !== '') {
                return oitem.MedTypeId == 2;
            }
            /* no MedTypeId on the row - recognise the surgeon order by its dilation medication list */
            return oitem.MedTypeName == 'Dilation Medication' || angular.isArray(oitem.DilationMedications) || angular.isArray(oitem.AscMedications);
        });
        let isAdmissionSaved = ($scope.cacheStorageItem.AdmissionId || 0) != 0;
        if (!isAdmissionSaved && savedOrders.length == 0) {
            return;
        }
        /* orders on screen before they are replaced (quick access / last save) - source for a missing time / Given By */
        $scope.RememberAdmitGeneralOrderValues();

        angular.forEach(savedOrders, function (Mitem) {
            Mitem.MedTypeId = 2;
            Mitem.MedTypeName = Mitem.MedTypeName || 'Dilation Medication';
            Mitem.DilationMedications = Mitem.DilationMedications || Mitem.AscMedications || [];
            /* Standing (1) / Live (2): from the order, else from its medications, else from the name, else Standing.
               The Summary and the Add screen group by it, so a row without it would not be shown at all. */
            let orderTypeName = readAdmitField(Mitem, 'OrderTypeName') || '';
            let orderTypeId = Number(readAdmitField(Mitem, 'OrderTypeId')) || 0;
            if (!orderTypeId) {
                let typedItem = Mitem.DilationMedications.concat(Mitem.GeneralOrders || []).filter(function (x) { return Number(readAdmitField(x, 'OrderTypeId')) > 0; })[0];
                orderTypeId = typedItem ? Number(readAdmitField(typedItem, 'OrderTypeId')) : 0;
            }
            if (!orderTypeId && orderTypeName) {
                orderTypeId = /live/i.test(orderTypeName) ? 2 : (/standing/i.test(orderTypeName) ? 1 : 0);
            }
            if (!orderTypeId) {
                /* not returned at all - same Standing/Live rule as a new order */
                orderTypeId = OrderTypeId;
                Mitem.IsOrderTypeInferred = true;
            }
            Mitem.OrderTypeId = orderTypeId;
            Mitem.ScreenTypeId = readAdmitField(Mitem, 'ScreenTypeId');
            Mitem.ScreenTypeName = readAdmitField(Mitem, 'ScreenTypeName');
            $scope.SetAdmitSurgeonOrderTypeFields(Mitem);
            Mitem.UserOrderId = Mitem.UserOrderId || 0;
            Mitem.DeleteInd = Mitem.DeleteInd || 'N';
            Mitem.ReviewedBy = Mitem.ReviewedBy || null;
            Mitem.ReviewedByName = Mitem.ReviewedByName || '';
            Mitem.ReviewedByPassword = '';
            Mitem.IsOrderReviewed = Mitem.IsOrderReviewed || false;
            /* Task 56803 - saved Surgeon (MD) reviewer: AMSCA / DEA come from the user list (AMSCAA column) */
            Mitem.DEA = $scope.HasCredentialValue(Mitem.DEA) ? Mitem.DEA : '';
            Mitem.AMSCA = $scope.HasCredentialValue(Mitem.AMSCA) ? Mitem.AMSCA : ($scope.HasCredentialValue(Mitem.AMSCAA) ? Mitem.AMSCAA : '');
            let reviewer = findAdmitUser(Mitem.ReviewedBy);
            if (reviewer && reviewer.SuffixId == 10) {
                Mitem.DEA = $scope.HasCredentialValue(reviewer.DEA) ? reviewer.DEA : Mitem.DEA;
                Mitem.AMSCA = $scope.HasCredentialValue(reviewer.AMSCAA) ? reviewer.AMSCAA : Mitem.AMSCA;
            }
            Mitem.DilationMedications = Mitem.DilationMedications || [];
            Mitem.GeneralOrders = Mitem.GeneralOrders || [];
            Mitem.PreOpMedications = Mitem.PreOpMedications || [];

            angular.forEach(Mitem.DilationMedications, function (item) {
                item.AscMedicationId = item.AscMedicationId || 0;
                item.DeleteInd = item.DeleteInd || 'N';
                item.MedicationNotes = item.MedicationNotes || '';
                item.DropTimings = item.DropTimings || [];
                angular.forEach(item.DropTimings, function (kitem) {
                    kitem.DropTimingId = kitem.DropTimingId || 0;
                    kitem.DeleteInd = kitem.DeleteInd || 'N';
                    kitem.MedicationDosage = kitem.MedicationDosage || '';
                    kitem.MedicationTime = normalizeAdmitOrderTime(readAdmitField(kitem, 'MedicationTime', 'GivenTime', 'Time'));
                    kitem.Remarks = kitem.Remarks || '';
                    let dropGivenBy = findAdmitUser(kitem.GivenBy);
                    kitem.GivenByname = kitem.GivenByname || kitem.GivenByName || (dropGivenBy ? dropGivenBy.FullName : '') || '';
                    kitem.LicenseNumber = kitem.LicenseNumber || (dropGivenBy ? dropGivenBy.LicenseNumber : '') || '';
                    kitem.GivenBy = ensureAdmitGivenByOption(kitem.GivenBy, kitem.GivenByname);
                    /* Task 13 - saved timings open in the summary; Edit + the Given By passcode reopens them */
                    kitem.IsEditview = kitem.DropTimingId != 0;
                    kitem.shownotes = !!kitem.Remarks;
                    kitem.IsEditDrop = true;
                });
            });
            angular.forEach(Mitem.GeneralOrders, function (gitem) {
                gitem.GeneralOrderId = gitem.GeneralOrderId || 0;
                gitem.DeleteInd = gitem.DeleteInd || 'N';
                gitem.Status = normalizeAdmitOrderStatus(readAdmitField(gitem, 'Status', 'OrderStatus'));
                gitem.GivenBy = readAdmitField(gitem, 'GivenBy', 'GivenById') || null;
                gitem.GivenByname = readAdmitField(gitem, 'GivenByname', 'GivenByFullName', 'GivenByUserName') || '';
                gitem.MedicationTime = normalizeAdmitOrderTime(readAdmitField(gitem, 'MedicationTime', 'GivenTime', 'StatusTime', 'OrderTime', 'Time'));
                if (!gitem.Status && gitem.MedicationTime) {
                    gitem.Status = 'Done';
                }
                if (gitem.Status === 'Done' && (!gitem.MedicationTime || !gitem.GivenBy)) {
                    let known = findAdmitGeneralOrderValues(gitem, Mitem.OrderTypeId);
                    if (known) {
                        gitem.MedicationTime = gitem.MedicationTime || known.MedicationTime;
                        gitem.GivenBy = gitem.GivenBy || known.GivenBy;
                        gitem.GivenByname = gitem.GivenByname || known.GivenByname;
                    }
                }
                if (gitem.Status !== 'Done') {
                    /* Not Done clears the time */
                    gitem.MedicationTime = '';
                }
                let orderGivenBy = findAdmitUser(gitem.GivenBy);
                gitem.GivenByname = gitem.GivenByname || gitem.GivenByName || (orderGivenBy ? orderGivenBy.FullName : '') || '';
                gitem.LicenseNumber = gitem.LicenseNumber || (orderGivenBy ? orderGivenBy.LicenseNumber : '') || '';
                gitem.GivenBy = ensureAdmitGivenByOption(gitem.GivenBy, gitem.GivenByname);
            });
        });

        let otherOrders = $scope.AdmissionObj.OrderDetails.filter(function (oitem) {
            return oitem.MedTypeId != 2;
        });
        $scope.AdmissionObj.OrderDetails = otherOrders.concat(savedOrders);
        $scope.SetReviewerCredentials($scope.AdmissionObj.OrderDetails);

        $scope.IsAdmitSurgeonOrders = savedOrders.some(function (Mitem) {
            return Mitem.DilationMedications.some(function (x) { return x.DeleteInd == 'N'; }) ||
                Mitem.GeneralOrders.some(function (x) { return x.DeleteInd == 'N'; });
        });

        if (admissionData.ODPupilSize !== undefined) {
            $scope.AdmissionObj.ODPupilSize = admissionData.ODPupilSize || "";
        }
        if (admissionData.OSPupilSize !== undefined) {
            $scope.AdmissionObj.OSPupilSize = admissionData.OSPupilSize || "";
        }
        if (admissionData.IsSurgeonOrdersTimeChecked !== undefined) {
            $scope.AdmitPreOpObj.IsSurgeonOrdersTimeChecked = admissionData.IsSurgeonOrdersTimeChecked || false;
        }
        let hasActiveMedication = savedOrders.some(function (Mitem) {
            return Mitem.DeleteInd === 'N' && Mitem.DilationMedications.some(function (x) { return x.DeleteInd === 'N'; });
        });
        $scope.AdmitPreOpObj.DisableSurgeonordersCheck = hasActiveMedication;
        if (hasActiveMedication) {
            $scope.AdmitPreOpObj.IsSurgeonOrdersTimeChecked = false;
        }

        $scope.AdmitDilationMedicationObj = angular.copy($scope.GetAdmitDilationMedicationObj());
        $scope.AdmitEditMedicationRef = null;
    };

    /* ---- ported from USMedicationOrderPopupCtrl: updateOrderDescription ---- */
